struct PhotoChallenge {
    char padding[40];
    int numTaken;

    int GetNumTaken() const { return numTaken; }
};

struct Challenges {
    char padding[728];
    PhotoChallenge *photo;
};

struct Beach {
    char padding[728];
    Challenges *challenges;

    Challenges *get_challenges() { return challenges; }
};

class Career {
public:
    bool PhotoExistsForLevel(int level);
};

struct Game {
    char padding[548];
    int level_id;

    int get_level_id() const { return level_id; }
};

struct FEMenu {
    char padding[0x70];
    FEMenu *next_sub;
};

struct MenuVtable {
    char padding[0x110];
    short adjustment;
    short reserved;
    void (*make_active)(void *, FEMenu *, bool);
};

extern Beach *g_beach_ptr;
extern Career *g_career;
extern Game *g_game_ptr;

__asm__(".equ g_beach_ptr, 0x0043F710");
__asm__(".equ g_career, 0x00427C9C");
__asm__(".equ g_game_ptr, 0x0046AC64");
__asm__(".equ PhotoExistsForLevel__6Careeri, 0x0025AF98");

class PhotoFrontEnd {
    char padding0[0x74];
    MenuVtable *vtable;
    char padding1[0xE8];
    FEMenu *selectMenu;
    FEMenu *saveMenu;
    FEMenu *develMenu;

    void MakeActive(FEMenu *menu, bool notify = true)
    {
        MenuVtable *table = vtable;
        table->make_active((char *)this + table->adjustment, menu, notify);
    }

public:
    void OnActivate();
};

extern "C" void base_activate(PhotoFrontEnd *)
    __asm__("OnActivate__15FEGraphicalMenu");
__asm__(".equ OnActivate__15FEGraphicalMenu, 0x001581E8");

void PhotoFrontEnd::OnActivate(void)
{
    base_activate(this);

    if (g_beach_ptr->get_challenges()->photo->GetNumTaken() == 1 &&
        g_career->PhotoExistsForLevel(g_game_ptr->get_level_id()))
    {
        saveMenu->next_sub = develMenu;
        MakeActive(saveMenu);
    }
    else if (g_beach_ptr->get_challenges()->photo->GetNumTaken() > 1)
    {
        if (g_career->PhotoExistsForLevel(g_game_ptr->get_level_id()))
            selectMenu->next_sub = saveMenu;
        else
            selectMenu->next_sub = develMenu;

        MakeActive(selectMenu);
    }
    else
    {
        MakeActive(develMenu);
    }
}
